{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "The bill also amends Tennessee Code Annotated Section 49-1-1002(a) to include child trafficking prevention and awareness education",
      "rationale": "Identifies the amended provision and the education topic being added; the precise placement within the list is not material."
    },
    {
      "proposition_id": "P2",
      "status": "partial",
      "summary_quote": "deletes specific language from Tennessee Code Annotated Section 49-6-1304.",
      "rationale": "Identifies the section subject to deletion but does not identify subdivision (a)(13)(B), whose text is not otherwise supplied in the bill."
    },
    {
      "proposition_id": "P3",
      "status": "partial",
      "summary_quote": "deletes specific language from Tennessee Code Annotated Section 49-6-1304.",
      "rationale": "Identifies the section subject to deletion but does not specify the second sentence of subsection (d), whose text is not otherwise supplied in the bill."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "Child trafficking is defined as a human trafficking offense where the victim is under 18 years old.",
      "rationale": "Conveys the offense category and the defining victim-age threshold; omission of the statutory cross-reference does not materially change the definition as summarized."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "This bill would require all public schools to provide child trafficking prevention and awareness education as part of health education for students in all grades from kindergarten through 12th grade.",
      "rationale": "Includes the mandatory instruction, all-public-school scope, health education placement, and every K–12 grade."
    },
    {
      "proposition_id": "P6",
      "status": "partial",
      "summary_quote": "Local education agencies (LEAs) and public charter schools must ensure this instruction is age- and grade-appropriate and based on health education standards adopted by the state board of education.",
      "rationale": "Includes the responsible entities, standards, and age and grade appropriateness, but omits annual advancement through developmentally appropriate instruction and skill building."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "These schools may use qualified social workers or healthcare professionals to help teach this material, provided those individuals meet specific requirements for teaching family life.",
      "rationale": "Conveys optional assistance by the specified qualified professionals and the condition that they meet family-life teaching requirements."
    },
    {
      "proposition_id": "P8",
      "status": "full",
      "summary_quote": "By August 1, 2026, and every August 1 after that, each public charter school governing body and local board of education must publish a plan on their website and submit it to the commissioner of education. This plan must describe the instruction methods for each grade, the qualifications of the instructors, and the resources used.",
      "rationale": "Covers the responsible bodies, initial and recurring deadline, submission and website publication duties, and required plan contents."
    },
    {
      "proposition_id": "P9",
      "status": "full",
      "summary_quote": "Additionally, by July 1, 2027, and every July 1 after that, these bodies must submit a report to the commissioner of education verifying that the required instruction was provided during the previous school year and providing the same details on methods, qualifications, and resources.",
      "rationale": "Covers the responsible bodies by reference, annual deadline, recipient, verification of preceding-year instruction, and required implementation details."
    },
    {
      "proposition_id": "P10",
      "status": "full",
      "summary_quote": "This act would take effect upon becoming law and applies to the 2026-2027 school year and following years.",
      "rationale": "States both the effective-date trigger and the initial and subsequent school years of application."
    }
  ]
}
